ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/paired_local_thimbles_collapse_to_one_mod_two_direction.md';PAIRED=ROOT/'research/nima/results/total-energy-paired-picard-lefschetz.json';LOCAL=ROOT/'research/voevodsky/results/local_legendre_thimble_and_ambient_parity.json';RESULT=ROOT/'research/voevodsky/results/paired_thimble_mod2_collapse.json';theta_plus=s.Matrix([1,0]);theta_minus=s.Matrix([0,1]);c=theta_plus+theta_minus;d=theta_plus-theta_minus;W=s.Matrix.hstack(c,d);mod2=lambda v:tuple(int(x)%2 for x in v);paired=json.loads(PAIRED.read_text(encoding='utf-8'));local=json.loads(LOCAL.read_text(encoding='utf-8'));text=PACKET.read_text(encoding='utf-8');checks={'source_two_nodes':paired['identities']['node_count']==2,'source_node_exchange':paired['identities']['node_exchange']=='t -> -t','change_index_two':abs(W.det())==2,'common_difference_equal_mod2':mod2(c)==mod2(d)==mod2(theta_plus+theta_minus),'mod2_span_rank_one':s.Matrix([[1,1],[1,1]]).rank(iszerofunc=lambda x:int(x)%2==0)==1,'ambient_four_classes':len(local['ambient_candidates'])==4,'local_parity_underdetermined':local['disposition']['twice_ambient_lift_parity']=='underdetermined among four classes','one_direction_boundary':'at most one mod-two direction' in text,'global_marking_required':'requires a global ordered Picard marking' in text};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.paired-thimble-mod2-collapse.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'paired_source_sha256':sha256(PAIRED.read_bytes()).hexdigest(),'local_result_sha256':sha256(LOCAL.read_bytes()).hexdigest(),'basis_change':[[int(x) for x in W.row(i)] for i in range(2)],'basis_change_determinant':int(W.det()),'common_mod2_class':list(mod2(c)),'checks':checks,'passed':all(checks.values()),'disposition':{'local_exchange_data':'one mod-two direction','ambient_extension_space':'two mod-two directions','missing':'global ordered Picard marking or two independent integral intersections'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
